import subprocess, json, sys, os, time
SOCK="/tmp/verify-output-muse-huyang/huyang.sock"
BIN="/tmp/huyang-5d244ad-workshop"
EVID="/tmp/verify-output-muse-huyang/evidence"
os.makedirs(EVID, exist_ok=True)
class MCP:
    def __init__(self):
        self.p=subprocess.Popen([BIN,"mcp","--profile","experimental","--socket",SOCK],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1)
        self.id=1
        self.raw_log=[]
    def req(self, method, params, save=None):
        oid=self.id; self.id+=1
        obj={"jsonrpc":"2.0","id":oid,"method":method,"params":params}
        req_bytes=len((json.dumps(obj)+"\n").encode())
        self.p.stdin.write(json.dumps(obj)+"\n"); self.p.stdin.flush()
        while True:
            line=self.p.stdout.readline()
            if not line: raise RuntimeError("MCP closed")
            try: resp=json.loads(line)
            except: continue
            if resp.get("id")==oid:
                resp_bytes=len(line.encode())
                if save:
                    open(save,"w").write(json.dumps({"request":obj,"response":resp,"req_bytes":req_bytes,"resp_bytes":resp_bytes},indent=1))
                return resp, req_bytes, resp_bytes
    def notify(self, method, params={}):
        self.p.stdin.write(json.dumps({"jsonrpc":"2.0","method":method,"params":params})+"\n"); self.p.stdin.flush()
    def close(self):
        try: self.p.stdin.close()
        except: pass
        try: self.p.terminate()
        except: pass
if __name__=="__main__":
    import sys
    spec=json.load(open(sys.argv[1]))
    m=MCP()
    try:
        r,_,_=m.req("initialize",{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"verify","version":"0.1"}})
        m.notify("notifications/initialized")
        for item in spec:
            name=item["tool"]; args=item["args"]; save=os.path.join(EVID,item["save"]) if "save" in item else None
            t0=time.time()
            resp,rb,sb=m.req("tools/call",{"name":name,"arguments":args},save=save)
            dt=time.time()-t0
            # print summary only
            print(f"=== {item.get('label',name)} req={rb} resp={sb} dt={dt:.2f}s save={save}")
            # print truncated text
            try:
                res=resp.get("result",{})
                # MCP result has content array
                content=res.get("content",[])
                for c in content[:2]:
                    t=c.get("text","")[:1500]
                    print(t)
                    print("---[truncated text len]", len(c.get("text","")))
                if "structuredContent" in res:
                    print("STRUCT:", json.dumps(res["structuredContent"])[:1500])
            except Exception as e:
                print("ERR",e)
    finally:
        m.close()
PY
echo RUNNER-OK

